// src/pages/Mesas.jsx  ← COPIA Y PEGA TODO ESTO
import { useEffect, useState } from "react";
import { getMesas, api } from "../services/api";
import { Table, Users } from "lucide-react";
import "./Mesas.css";

export default function Mesas() {
  const [mesas, setMesas] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarMesas();
  }, []);

  const cargarMesas = async () => {
    try {
      const data = await getMesas();
      setMesas(data);
    } catch (err) {
      alert("Error cargando mesas");
    } finally {
      setLoading(false);
    }
  };

  // VERSIÓN 100% FUNCIONAL usando tus endpoints ocupar/liberar
  const toggleMesa = async (mesa) => {
    try {
      let response;

      if (mesa.ocupada) {
        // LIBERAR MESA
        response = await api.post(`/api/mesas/${mesa.id}/liberar/`);
      } else {
        // OCUPAR MESA (llenamos al máximo)
        response = await api.post(`/api/mesas/${mesa.id}/ocupar/`, {
          cantidad_clientes: mesa.capacidad,
        });
      }

      // Si el backend dice que todo bien → actualizamos el frontend
      if (response.data.success) {
        setMesas((prev) =>
          prev.map((m) =>
            m.id === mesa.id
              ? {
                  ...m,
                  ocupada: !mesa.ocupada,
                  clientes_actuales: mesa.ocupada ? 0 : mesa.capacidad,
                }
              : m
          )
        );
      } else {
        alert("No se pudo cambiar el estado de la mesa");
      }
    } catch (err) {
      console.error("Error al cambiar estado:", err);
      alert("Error al cambiar estado");
    }
  };

  if (loading) return <div className="loader">Cargando mesas...</div>;

  return (
    <div className="mesas-page">
      <div className="mesas-bg"></div>
      <div className="mesas-overlay"></div>

      <div className="mesas-content">
        <h1 className="mesas-title">CONTROL DE MESAS</h1>
        <p className="mesas-subtitle">
          Haz click en una mesa para ocuparla o liberarla
        </p>

        <div className="mesas-grid">
          {mesas.map((mesa) => {
            const esOcupada = mesa.ocupada;
            const Icon = esOcupada ? Users : Table;
            const color = esOcupada ? "#e74c3c" : "#10b981";

            return (
              <div
                key={mesa.id}
                className="mesa-card"
                onClick={() => toggleMesa(mesa)}
                style={{ "--estado-color": color }}
              >
                <div className="mesa-header">
                  <Icon size={40} />
                  <span className="mesa-numero">Mesa {mesa.numero}</span>
                </div>

                <div className="mesa-body">
                  <div className="estado-badge">
                    <div className="punto"></div>
                    <span style={{ color }}>
                      {esOcupada ? "OCUPADA" : "LIBRE"}
                    </span>
                  </div>
                  <p>Capacidad: {mesa.capacidad} personas</p>
                  <p className="clientes-actuales">
                    {mesa.clientes_actuales} / {mesa.capacidad} clientes
                  </p>
                </div>

                <div className="mesa-glow"></div>
              </div>
            );
          })}
        </div>

        <div className="leyenda">
          <div>
            <span style={{ background: "#10b981" }}></span> Libre
          </div>
          <div>
            <span style={{ background: "#e74c3c" }}></span> Ocupada
          </div>
        </div>
      </div>
    </div>
  );
}
